DigiBoardMap.install=()=>{
(()=>{
const R=PraatpadRoutes,W=1672,H=941;
const anchors=[[151, 763], [151, 687], [161, 644], [203, 613], [249, 582], [276, 536], [263, 485], [264, 437], [317, 403], [381, 384], [446, 376], [510, 374], [569, 382], [627, 380], [681, 366], [755, 341], [805, 315], [850, 293], [901, 284], [952, 290], [1037, 294], [1096, 294], [1154, 296], [1208, 307], [1262, 322], [1318, 326], [1377, 329], [1428, 354], [1466, 390], [1507, 429], [1540, 473], [1538, 521], [1506, 563], [1499, 628]];
const connections=[{"id": "kristalgrot", "type": "tunnel", "from": 28, "exits": [32], "label": "Kristalgrot T1"}, {"id": "poort-heen", "type": "portal", "from": 8, "exits": [26], "label": "Maanpoort P1 · naar het kristaleiland"}, {"id": "poort-terug", "type": "portal", "from": 26, "exits": [8], "label": "Maanpoort P1 · terug naar het boseiland"}];
const fit=(w,h)=>{const scale=Math.min(w/W,h/H);return{scale,x:(w-W*scale)/2,y:(h-H*scale)/2}};
const legs=anchors.slice(0,-1).map((p,i)=>[p,anchors[i+1]]);
const map=(p,f)=>[p[0]*f.scale+f.x,p[1]*f.scale+f.y];
R.layout=(b,w,h)=>{const f=fit(w,h);return{points:anchors.map(p=>map(p,f)),tileWidth:64*f.scale,tileHeight:46*f.scale,pawnOffsetX:0,pawnOffsetY:0,scale:f.scale};};
R.coordinates=()=>anchors.map(([x,y])=>[x/W,y/H]);
R.routeGeometry=(b,w,h,c,to=c.exits[0])=>{const f=fit(w,h),points=(to===c.from+1?legs[c.from]:[anchors[c.from],anchors[to]]).map(p=>map(p,f));return{points,d:'M '+points.map(p=>p.join(' ')).join(' L '),from:points[0],to:points.at(-1),layout:R.layout(b,w,h),clear:true};};
R.mainPath=(b,w,h,stop=33)=>Array.from({length:stop},(_,i)=>R.routeGeometry(b,w,h,{from:i,exits:[i+1]}).d).join(' ');
R.artwork=()=>'';
R.portPosition=(b,w,h,c)=>R.layout(b,w,h).points[c.from];
function step(from,to,t,w,h){return{point:map(R.along(legs[from],Math.max(0,Math.min(1,t))),fit(w,h)),opacity:1,kind:from>=14&&from<=19?'bridge':'walk',boat:null};}
function pawnDepth(point,w,h){return 7;}
globalThis.PraatpadWorld={anchors,legs,fit,connections,step,pawnDepth,bridgeStart:14,boatMarkup:()=>'',departure:[0,0],arrival:[0,0],duration:()=>800};
globalThis.PraatpadCity={fit,anchors,angles:Array(34).fill(0)};
})();
// A scalable, colorable game piece; no embedded raster assets or font symbols.
PraatpadCity.pawn=(number='')=>`<svg viewBox="0 0 48 68" aria-hidden="true" focusable="false"><ellipse cx="24" cy="63" rx="21" ry="4" fill="#102e3a" opacity=".22"/><path d="M17 25C9 21 10 7 18 4C30-1 40 13 32 23L30 25C29 29 30 35 34 42L41 53C44 57 42 62 37 63H11C6 62 4 57 7 53L14 42C18 35 19 29 17 25Z" fill="currentColor" stroke="#fffdf4" stroke-width="3" stroke-linejoin="round"/><path d="M29 5C38 12 34 21 29 24C26 30 29 38 33 45L39 55C41 58 39 60 36 60H29C33 55 26 44 24 35C22 29 23 25 26 21C30 16 31 10 29 5Z" fill="#102e3a" opacity=".2"/><path d="M16 14C16 10 19 7 23 7" fill="none" stroke="#fff" stroke-opacity=".4" stroke-width="3" stroke-linecap="round"/><path d="M10 54C19 57 30 57 39 54" fill="none" stroke="#fff" stroke-opacity=".4" stroke-width="2"/><text x="24" y="48" fill="#fff" text-anchor="middle" font-family="Arial,sans-serif" font-size="17" font-weight="700">${number}</text></svg>`;
PraatpadCity.terminal=end=>`<span class="city-terminal-name">${end?'FINISH':'START'}</span><span class="city-terminal-sign" aria-hidden="true">${end?'<svg viewBox="0 0 40 32"><path d="M7 29V3" stroke="#163d4c" stroke-width="3"/><path d="M8 3H34V21H8Z" fill="#fff" stroke="#163d4c" stroke-width="2"/><path d="M8 3h7v6H8zm13 0h7v6h-7zm-6 6h6v6h-6zm13 0h6v6h-6zm-20 6h7v6H8zm13 0h7v6h-7z" fill="#163d4c"/></svg>':'<svg viewBox="0 0 40 32"><path d="M6 16H32M23 6L33 16L23 26" fill="none" stroke="#167562" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg>'}</span>`;


};
DigiBoardMap.positions={'kristalgrot':[1300,548],'poort-heen':[530,264],'poort-terug':[1210,215]};
DigiBoardMap.depthRoutes={tree:{from:5,exits:[7]},bridge:{from:14,exits:[20]}};
DigiBoardMap.connectRuntime=host=>{
const {$,root,Routes,s,current,routeConnections,reduced,drawMap,renderControls}=host;
function tunnelPose(t,from,to){return DigiBoardSpatial.pose('fantasie-eilanden',t,from,to);}
globalThis.FantasieTunnel={pose:tunnelPose,duration:6800,from:28,to:32};
function drawTunnelState(){
 const phase=host.anim?.tunnelPhase||'';root.dataset.tunnelPhase=phase;
 const trace=$('fantasie-underground');trace.style.visibility=phase==='hidden'?'visible':'hidden';
 if(phase==='hidden'){
  const k=host.anim.tunnelProgress||0,point=Routes.along(DigiBoardSpatial.trace('fantasie-eilanden'),k);
  $('fantasie-underground-dot').setAttribute('cx',point[0]);$('fantasie-underground-dot').setAttribute('cy',point[1]);
 }
}
function animateTunnel(record,token){
 host.anim.pos=record.from;
 if(reduced()){host.anim.pos=record.to;drawMap();return Promise.resolve();}
 root.classList.add('pp-stepping');
 $('pp-transit-label').hidden=false;
 return new Promise(resolve=>{
  let start=null,raf=0,ended=false;
  const done=()=>{if(ended)return;ended=true;cancelAnimationFrame(raf);host.transportCancel=null;
   if(host.anim){delete host.anim.stepPoint;delete host.anim.cityTunnelOpacity;delete host.anim.tunnelScale;delete host.anim.tunnelPhase;delete host.anim.tunnelProgress;}
   root.classList.remove('pp-stepping');root.dataset.tunnelPhase='';$('fantasie-underground').style.visibility='hidden';$('pp-transit-label').hidden=true;resolve();
  };
  host.transportCancel=done;
  const frame=now=>{
   if(token!==host.run||!host.anim){done();return;}
   start??=now;const t=Math.min(1,(now-start)/6800),pose=tunnelPose(t,record.from,record.to),f=PraatpadWorld.fit($('pp-map').clientWidth,$('pp-map').clientHeight);
   host.anim.stepPoint=[pose.point[0]*f.scale+f.x,pose.point[1]*f.scale+f.y];
   host.anim.cityTunnelOpacity=pose.opacity;host.anim.tunnelScale=pose.scale;host.anim.tunnelPhase=pose.phase;host.anim.tunnelProgress=pose.progress;
   $('pp-transit-label').textContent=pose.phase==='hidden'?'T1 · Onder de grond → vak 32':pose.phase==='exit'||pose.phase==='arrive'?'T1 · De tunnel uit bij 32':'T1 · De kristalgrot in bij 28';
   drawMap();
   if(t===1){host.anim.pos=record.to;done();drawMap();}else raf=requestAnimationFrame(frame);
  };raf=requestAnimationFrame(frame);
 });
}

const portalSites={8:[247,231],26:[1307,158]},portalDuration=4200;
function portalPose(t,from,to){
 const a=portalSites[from],b=portalSites[to],at=(p,x,y)=>[p[0]+120*x,p[1]+120*y],frontA=at(a,.5,.92),frontB=at(b,.5,.92),deepA=at(a,.5,.61),deepB=at(b,.5,.61),lerp=(p,q,k)=>p.map((v,i)=>v+(q[i]-v)*k),clamp=x=>Math.max(0,Math.min(1,x));
 if(t<.12)return{point:lerp(PraatpadWorld.anchors[from],frontA,t/.12),scale:1,opacity:1,phase:'approach'};
 if(t<.4){const k=(t-.12)/.28;return{point:lerp(frontA,deepA,k),scale:1-.45*k,opacity:1-clamp((k-.35)/.65),phase:'enter'};}
 if(t<.6)return{point:deepA,scale:.55,opacity:0,phase:'hidden'};
 if(t<.88){const k=(t-.6)/.28;return{point:lerp(deepB,frontB,k),scale:.55+.45*k,opacity:clamp(k/.65),phase:'exit'};}
 return{point:lerp(frontB,PraatpadWorld.anchors[to],(t-.88)/.12),scale:1,opacity:1,phase:'arrive'};
}
globalThis.FantasiePortal={pose:portalPose,duration:portalDuration,sites:portalSites};
function drawPortalState(){
 root.dataset.portalPhase=host.anim?.portalPhase||'';
 const glow=host.anim?.portalPhase?Math.max(0,Math.sin((host.anim.portalProgress||0)*Math.PI))*.85:0;
 root.querySelectorAll('.fantasie-portal-aura').forEach(e=>e.style.opacity=glow);
}
function animatePortal(record,token){
 host.anim.pos=record.from;if(reduced()){host.anim.pos=record.to;drawMap();return Promise.resolve();}
 root.classList.add('pp-stepping');$('pp-transit-label').hidden=false;
 return new Promise(resolve=>{let start=null,raf=0,ended=false;
  const done=()=>{if(ended)return;ended=true;cancelAnimationFrame(raf);host.transportCancel=null;if(host.anim){delete host.anim.stepPoint;delete host.anim.cityTunnelOpacity;delete host.anim.tunnelScale;delete host.anim.portalPhase;delete host.anim.portalProgress;}root.dataset.portalPhase='';root.classList.remove('pp-stepping');$('pp-transit-label').hidden=true;root.querySelectorAll('.fantasie-portal-aura').forEach(e=>e.style.opacity=0);resolve();};host.transportCancel=done;
  const frame=now=>{if(token!==host.run||!host.anim){done();return;}start??=now;const t=Math.min(1,(now-start)/portalDuration),pose=portalPose(t,record.from,record.to),f=PraatpadWorld.fit($('pp-map').clientWidth,$('pp-map').clientHeight);
   host.anim.stepPoint=[pose.point[0]*f.scale+f.x,pose.point[1]*f.scale+f.y];host.anim.cityTunnelOpacity=pose.opacity;host.anim.tunnelScale=pose.scale;host.anim.portalPhase=pose.phase;host.anim.portalProgress=t;
   $('pp-transit-label').textContent=pose.phase==='hidden'?'P1 · Tussen de eilanden':pose.phase==='exit'||pose.phase==='arrive'?'P1 · De poort uit bij '+record.to:'P1 · De lichtsluier in bij '+record.from;drawMap();
   if(t===1){host.anim.pos=record.to;done();drawMap();}else raf=requestAnimationFrame(frame);
  };raf=requestAnimationFrame(frame);
 });
}


function connectionRule(c){if(c.type==='portal')return `P1: land op ${c.from}. Stap de lichtsluier in en verschijn bij ${c.exits[0]}. Per worp volgt één poortsprong; bij aankomst spring je niet meteen terug. Doe de opdracht op het eindvak.`;if(c.type==='tunnel')return `T1: land op vak ${c.from}. Loop de kristalgrot in, ga onder de grond en kom bij vak ${c.exits[0]} weer boven. Doe daar de opdracht.`;if(c.type==='extra_steps')return `Land op vak ${c.from}: ga ${Math.abs(c.exits[0]-c.from)} ${c.exits[0]>c.from?'stappen vooruit':'stap'+(c.from-c.exits[0]===1?'':'pen')+' terug'} naar vak ${c.exits[0]}. Doe daar de opdracht.`;const t=Routes.getType(c.type);return `${c.enabled===false?'Gesloten. ':''}${c.optional?'Je mag ook op de ingang blijven. ':''}${t.rule==='history'?`Vanaf vak ${c.from}: kies een eerder eindvak van deze pion. Beurt en sleutels blijven staan.`:Routes.ruleText(c)}`;}
return{rule:connectionRule,draw(){drawTunnelState();drawPortalState();},adjustPawn(el,w,h){if(s().board.cityArtwork&&!host.anim?.tunnelPhase&&!host.anim?.portalPhase){const f=PraatpadWorld.fit(w,h),x=(parseFloat(el.style.left)-f.x)/f.scale,y=(parseFloat(el.style.top)-f.y)/f.scale;if(x>=705&&x<=1005&&y>=270&&y<=380){const dy=25*Math.max(0,Math.min(1,(x-705)/50,(1005-x)/53));el.style.top=(parseFloat(el.style.top)+dy*f.scale)+'px';}}},animate(record,token){const c=routeConnections().find(c=>c.id===record.id||c.from===record.from);if(c?.type==='tunnel')return animateTunnel(record,token);if(c?.type==='portal')return animatePortal(record,token);return null;}};
};
